const $=id=>document.getElementById(id);let token='',page=1,epoch=0;const links={CONTRAT:'missions.html',FACTURE:'billing.html',CRA:'missions.html',RELANCE:'crm.html',RENOUVELLEMENT:'missions.html'};
async function load(){const n=++epoch;const q=new URLSearchParams({page,horizon:$('horizon').value,kind:$('kind').value,priority:$('priority').value});const r=await fetch('/api/admin/alerts?'+q,{headers:{Authorization:'Bearer '+token}}),d=await r.json();if(!r.ok)throw Error(d.error);if(n!==epoch||!token)return;$('summary').textContent=d.as_of+' — horizon '+d.horizon+' jours, retards inclus';$('alert-counts').replaceChildren();for(const [label,value] of [['En retard',d.urgent],...Object.entries(d.counts)]){const card=document.createElement('div'),n=document.createElement('strong');card.className='count';n.textContent=value;card.append(n,document.createTextNode(label));$('alert-counts').append(card)}$('rows').replaceChildren();for(const x of d.items){const tr=document.createElement('tr');for(const v of [x.priority,x.kind,x.label,x.due,x.days_remaining<0?Math.abs(x.days_remaining)+' j de retard':x.days_remaining===0?'Aujourd’hui':'Dans '+x.days_remaining+' j',x.details]){const td=document.createElement('td');td.textContent=v;tr.append(td)}const td=document.createElement('td'),a=document.createElement('a');a.href=links[x.kind];a.textContent='Consulter';td.append(a);tr.append(td);$('rows').append(tr)}if(!d.items.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=7;td.textContent='Aucune alerte pour ces critères.';tr.append(td);$('rows').append(tr)}$('pages').textContent='Page '+page+' · '+d.total+' alerte(s)';$('prev').disabled=page===1;$('next').disabled=page*25>=d.total}
async function refresh(){try{await load();$('notice').textContent='Alertes actualisées.'}catch(e){$('notice').textContent=e.message}}
$('login-form').onsubmit=async e=>{e.preventDefault();token=$('token').value;$('token').value='';page=1;try{await load();$('login').hidden=true;$('workspace').hidden=false;$('notice').textContent='Connecté.'}catch(e){token='';$('notice').textContent=e.message}};
$('logout').onclick=()=>{epoch++;token='';$('rows').replaceChildren();$('summary').textContent='';$('alert-counts').replaceChildren();$('pages').textContent='';$('workspace').hidden=true;$('login').hidden=false;$('notice').textContent='Déconnecté.'};$('filter').onsubmit=e=>{e.preventDefault();page=1;refresh()};$('prev').onclick=()=>{if(page>1){page--;refresh()}};$('next').onclick=()=>{page++;refresh()};
